"""Undoable, ID-preserving edits for the Stage 5 editable street inputs.

The functions are also usable by deterministic Blender tests. They validate the
authored contract before making a change. The Blender operators add native undo;
direct function calls deliberately do not manufacture their own undo steps.
Register with ``register(runtime.refresh)`` to update the generated result after
an operation. Current native GN paths read vertex moves without Python refresh.
"""

import math
import struct
from contextlib import contextmanager

import bpy
import bmesh
from bpy.props import EnumProperty, FloatProperty, IntProperty

from . import model


_refresh_callback = None
_transaction_depth = 0


def set_refresh_callback(callback):
    global _refresh_callback
    _refresh_callback = callback


def is_editing():
    """Runtime handlers can avoid observing a partially committed edit."""
    return _transaction_depth > 0


@contextmanager
def _transaction(controller):
    global _transaction_depth
    _transaction_depth += 1
    try:
        yield
    finally:
        _transaction_depth -= 1
    if _refresh_callback is not None:
        _refresh_callback(controller)


def controller_for_object(obj):
    if obj is None:
        return None
    if obj.get('blosm_original_span_network'):
        return obj
    if getattr(getattr(obj, "st_network", None), "enabled", False):
        return obj
    source = getattr(obj, "st_source_controller", None)
    if source is not None:
        return source
    return getattr(obj, "st_generated_controller", None)


def _network(controller):
    if controller is None:
        raise ValueError("Select a Street source or its network controller")
    if controller.get('blosm_original_span_network'):
        raise ValueError('Managed topology edits for the original-span candidate require its new binding compiler')
    # BMesh edits must reach Mesh before normalization/validation sees them.
    for obj in bpy.context.objects_in_mode:
        if obj.type == 'MESH' and controller_for_object(obj) == controller:
            obj.update_from_editmode()
    return model.read_network(controller)


def _section(controller, section_id):
    network = _network(controller)
    section_id = int(section_id)
    try:
        source = network.section_sources[section_id]
    except KeyError as exc:
        raise ValueError(f"No Section {section_id} in this network") from exc
    return network, source


def _source_object(source):
    # The source lookup carries persistent IDs separately from these transient
    # Blender indices; no vertex indices are persisted in the registry.
    return source.object


@contextmanager
def _editable_bmesh(obj):
    edit_mode = obj.mode == 'EDIT'
    bm = bmesh.from_edit_mesh(obj.data) if edit_mode else bmesh.new()
    if not edit_mode:
        bm.from_mesh(obj.data)
    try:
        yield bm
        if edit_mode:
            bmesh.update_edit_mesh(obj.data, loop_triangles=False, destructive=True)
            obj.update_from_editmode()
        else:
            bm.to_mesh(obj.data)
            obj.data.update()
    finally:
        if not edit_mode:
            bm.free()


def _layers(bm):
    result = (
        bm.edges.layers.int.get("st_section_id"),
        bm.edges.layers.float.get("st_width"),
        bm.edges.layers.float.get("st_offset"),
        bm.verts.layers.int.get("st_endpoint_role"),
    )
    if any(layer is None for layer in result):
        raise ValueError("The source is missing required street mesh attributes")
    return result


def _selected_section(context, explicit=-1):
    obj = context.active_object
    controller = controller_for_object(obj)
    if explicit >= 0:
        if controller is None:
            raise ValueError("Select a Street source or its network controller")
        return controller, explicit
    if obj is None or obj.type != 'MESH' or obj == controller:
        raise ValueError("Select a Section edge in a Street source")
    if obj.mode == 'EDIT':
        bm = bmesh.from_edit_mesh(obj.data)
        layer = bm.edges.layers.int.get("st_section_id")
        if layer is None:
            raise ValueError("This mesh has no st_section_id edge attribute")
        selected = {edge[layer] for edge in bm.edges if edge.select}
    else:
        attr = obj.data.attributes.get("st_section_id")
        if attr is None or attr.domain != 'EDGE' or attr.data_type != 'INT':
            raise ValueError("This mesh has no valid st_section_id edge attribute")
        selected = {attr.data[edge.index].value for edge in obj.data.edges if edge.select}
        all_sections = {entry.value for entry in attr.data}
        if not selected and len(all_sections) == 1:
            selected = all_sections
    if len(selected) != 1:
        raise ValueError("Select edges from exactly one Section, or supply its Section ID")
    section_id = selected.pop()
    return controller, section_id


def set_section_parameters(controller, section_id, *, width=None, offset=None, interpolation=None):
    """Set all Section edges coherently; dimensions remain physical metres.

    Interpolation 0 follows the exact polyline and 3 uses an interpolating
    cubic through its vertices. These are supported modes, not a continuous
    smoothing amount. A legacy source gains the attribute when first set.
    """
    if controller.get('blosm_original_span_network'):
        from .original_span_editing import set_parameters
        return set_parameters(controller,section_id,width=width,offset=offset,interpolation=interpolation)
    _input, source = _section(controller, section_id)
    def stored_float(value, label, positive=False):
        try:
            value = struct.unpack('f', struct.pack('f', float(value)))[0]
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(f"{label} must fit a finite mesh float") from exc
        if not math.isfinite(value) or (positive and value <= 0):
            raise ValueError(f"{label} must be finite" + (" and strictly positive" if positive else ""))
        return value

    if width is not None:
        width = stored_float(width, "Section width", positive=True)
    if offset is not None:
        offset = stored_float(offset, "Section offset")
    if interpolation is not None:
        if type(interpolation) is not int or interpolation not in model.INTERPOLATION_MODES:
            raise ValueError("Section interpolation must be integer 0 (exact polyline) or 3 (smooth cubic)")
    obj = _source_object(source)
    with _transaction(controller):
        with _editable_bmesh(obj) as bm:
            ids, widths, offsets, _roles = _layers(bm)
            modes = (bm.edges.layers.int.get(model.INTERPOLATION_ATTRIBUTE)
                     or bm.edges.layers.int.new(model.INTERPOLATION_ATTRIBUTE)) if interpolation is not None else None
            for edge in bm.edges:
                if edge[ids] == section_id:
                    if width is not None:
                        edge[widths] = width
                    if offset is not None:
                        edge[offsets] = offset
                    if interpolation is not None:
                        edge[modes] = interpolation
    return section_id


def subdivide_section(controller, section_id, *, cuts=1):
    """Subdivide every edge of one Section without allocating a logical ID.

    New vertices have interior role 0. Existing endpoints and attachment records
    are untouched. Width/offset/interpolation are written explicitly after BMesh subdivision,
    rather than relying on integer-attribute interpolation.
    """
    _input, source = _section(controller, section_id)
    if type(cuts) is not int or not 1 <= cuts <= 32:
        raise ValueError("Subdivision cuts must be an integer from 1 to 32")
    obj = _source_object(source)
    with _transaction(controller):
        with _editable_bmesh(obj) as bm:
            ids, widths, offsets, roles = _layers(bm)
            modes = bm.edges.layers.int.get(model.INTERPOLATION_ATTRIBUTE)
            edges = [edge for edge in bm.edges if edge[ids] == section_id]
            width, offset = edges[0][widths], edges[0][offsets]
            interpolation = edges[0][modes] if modes is not None else None
            bm.verts.index_update()
            anchor_index = edges[0].verts[0].index
            original_roles = [vertex[roles] for vertex in bm.verts]
            bmesh.ops.subdivide_edges(bm, edges=edges, cuts=cuts, use_grid_fill=False)
            bm.verts.index_update()
            bm.verts.ensure_lookup_table()
            for index, vertex in enumerate(bm.verts):
                # Subdivision can interpolate custom data on existing vertices
                # too; restore their authored role explicitly. This operation
                # only appends vertices: no old vertex is deleted/reordered.
                # Do not key a dictionary by BMVert wrapper identity: Blender
                # 5.2 may replace those Python wrappers during an operation.
                vertex[roles] = original_roles[index] if index < len(original_roles) else 0
            # Follow connectivity rather than interpolated integer IDs to find
            # all new edges of this independently authored Section chain.
            pending = [bm.verts[anchor_index]]
            visited = set()
            while pending:
                vertex = pending.pop()
                key = vertex.index
                if key in visited:
                    continue
                visited.add(key)
                for edge in vertex.link_edges:
                    edge[ids] = section_id
                    edge[widths] = width
                    edge[offsets] = offset
                    if modes is not None:
                        edge[modes] = interpolation
                    pending.append(edge.other_vert(vertex))
    return section_id


def reverse_section(controller, section_id):
    """Reverse authored direction while preserving the physical Street.

    This initial schema has no station-anchored features or asymmetric profile
    payloads. The orientation flag is reversed locally, without altering shared
    profile definitions. Both connector ends and Street traversal are remapped;
    IDs, Bundle order and the physical outward directions remain unchanged.
    """
    _input, source = _section(controller, section_id)
    obj = _source_object(source)
    registry = controller.st_network
    items = [item for street in registry.streets for item in street.items
             if item.kind == 'SECTION' and item.section_id == section_id]
    members = [member for connector in registry.connectors for member in connector.members
               if member.section_id == section_id]
    sections = [section for section in registry.sections if section.section_id == section_id]
    with _transaction(controller):
        with _editable_bmesh(obj) as bm:
            ids, _widths, offsets, roles = _layers(bm)
            edges = [edge for edge in bm.edges if edge[ids] == section_id]
            vertices = {vertex for edge in edges for vertex in edge.verts}
            for vertex in vertices:
                if vertex[roles] in (1, 2):
                    vertex[roles] = 3 - vertex[roles]
            for edge in edges:
                edge[offsets] = -edge[offsets]
        for item in items:
            item.forward = not item.forward
        for member in members:
            member.section_end = 1 - member.section_end
        for section in sections:
            if hasattr(section, "profile_reversed"):
                section.profile_reversed = not section.profile_reversed
    return section_id


def _copy_mesh_rows(name, vertex_rows, edge_rows, target_frame):
    """Copy actual mesh rows, retaining every supported POINT/EDGE attribute.

    Each row is (source object, mesh index). The target frame is a world matrix.
    This avoids BMesh interpolation when moving entire Sections between objects.
    Unknown attribute representations are rejected before any source changes.
    """
    inverse = target_frame.inverted()
    lookup = {(obj.as_pointer(), index): i for i, (obj, index) in enumerate(vertex_rows)}
    points = [inverse @ obj.matrix_world @ obj.data.vertices[index].co
              for obj, index in vertex_rows]
    edges = [tuple(lookup[(obj.as_pointer(), vertex)]
                   for vertex in obj.data.edges[index].vertices)
             for obj, index in edge_rows]
    schema = {}
    for obj in {obj for obj, _index in vertex_rows}:
        for attribute in obj.data.attributes:
            # Connectivity belongs to the new row indices; copying Blender's
            # internal .edge_verts table would overwrite the remapped edges.
            if attribute.name in {"position", ".edge_verts", ".corner_vert", ".corner_edge"}:
                continue
            if attribute.domain not in ('POINT', 'EDGE'):
                if len(attribute.data):
                    raise ValueError(f"Cannot regroup attribute {attribute.name} on {attribute.domain}")
                continue
            signature = (attribute.data_type, attribute.domain)
            if attribute.name in schema and schema[attribute.name] != signature:
                raise ValueError(f"Attribute {attribute.name} has incompatible types between sources")
            schema[attribute.name] = signature
    mesh = bpy.data.meshes.new(name)
    try:
        mesh.from_pydata(points, edges, [])
        for name, (kind, domain) in schema.items():
            destination = mesh.attributes.get(name) or mesh.attributes.new(name, kind, domain)
            rows = vertex_rows if domain == 'POINT' else edge_rows
            for output_index, (obj, input_index) in enumerate(rows):
                source = obj.data.attributes.get(name)
                if source is None:
                    continue  # A non-contract custom attribute has its default.
                value = source.data[input_index]
                prop = next((prop for prop in ('value', 'vector', 'color')
                             if hasattr(value, prop)), None)
                if prop is None:
                    raise ValueError(f"Cannot regroup attribute {name} ({kind}); representation unsupported")
                field = getattr(value, prop)
                if not isinstance(field, (int, float, bool, str)):
                    field = tuple(field)
                setattr(destination.data[output_index], prop, field)
        mesh.update()
        return mesh
    except Exception:
        bpy.data.meshes.remove(mesh)
        raise


def _input_collections(collection):
    if collection is None:
        return []
    return [collection, *(child for nested in collection.children
                          for child in _input_collections(nested))]


def separate_street(controller, street_id):
    """Move one complete logical Street into its own source object.

    IDs, Street item order, connector ends, profiles and physical placement are
    unchanged. All Sections stay complete; coincident endpoints are not welded.
    The operation is Object Mode only and never replaces a controller object.
    Already separate Streets simply return their existing source object.
    """
    network = _network(controller)
    street = next((s for s in network.canonical.streets if s.id == street_id), None)
    if street is None:
        raise ValueError(f"No Street {street_id} in this network")
    section_ids = {section_id for section_id, _forward in street.sections}
    sources = {network.section_sources[sid].object for sid in section_ids}
    if any(source.mode != 'OBJECT' for source in sources):
        raise ValueError("Separate a Street in Object Mode")
    if any(source.library is not None or source.data.library is not None for source in sources):
        raise ValueError("Make linked source objects local before separating a Street")
    source_section_ids = {obj: {sid for sid, source in network.section_sources.items()
                                if source.object == obj} for obj in sources}
    if len(sources) == 1:
        only = next(iter(sources))
        if only != controller and source_section_ids[only] == section_ids:
            return only

    # Compose rows in Street traversal order but copy endpoint roles verbatim:
    # object storage order is deliberately independent of authored direction.
    vertex_rows, edge_rows = [], []
    selected_vertices = {obj: set() for obj in sources}
    selected_edges = {obj: set() for obj in sources}
    for sid, _forward in street.sections:
        source = network.section_sources[sid]
        obj = source.object
        vertex_rows.extend((obj, index) for index in source.vertex_indices)
        edge_rows.extend((obj, index) for index in source.edge_indices)
        selected_vertices[obj].update(source.vertex_indices)
        selected_edges[obj].update(source.edge_indices)

    prepared = []
    replacements = {}
    new_object = None
    created_collection = None
    registry = controller.st_network
    old_grouped, old_base = registry.grouped_object, registry.use_controller_mesh
    old_collection = registry.source_collection
    old_data = {obj: obj.data for obj in sources}
    removed_links = []
    try:
        new_mesh = _copy_mesh_rows(f"Street {street_id} source", vertex_rows, edge_rows,
                                   controller.matrix_world)
        prepared.append(new_mesh)
        for obj in sources:
            vertices = [(obj, v.index) for v in obj.data.vertices
                        if v.index not in selected_vertices[obj]]
            edges = [(obj, e.index) for e in obj.data.edges
                     if e.index not in selected_edges[obj]]
            if vertices:
                replacements[obj] = _copy_mesh_rows(obj.data.name + " regrouped", vertices,
                                                    edges, obj.matrix_world)
                prepared.append(replacements[obj])
            else:
                if obj == controller:
                    replacements[obj] = bpy.data.meshes.new(obj.data.name + " empty base")
                    prepared.append(replacements[obj])
                else:
                    replacements[obj] = None
        with _transaction(controller):
            try:
                collection = registry.source_collection
                if collection is None:
                    created_collection = bpy.data.collections.new(controller.name + " sources")
                    bpy.context.scene.collection.children.link(created_collection)
                    collection = created_collection
                    registry.source_collection = collection
                new_object = bpy.data.objects.new(f"Street {street_id} source", new_mesh)
                new_object.matrix_world = controller.matrix_world.copy()
                new_object.st_source_controller = controller
                new_object.show_in_front = True
                new_object.display_type = 'WIRE'
                new_object.hide_render = True
                collection.objects.link(new_object)
                input_collections = _input_collections(collection)
                for obj, mesh in replacements.items():
                    if mesh is not None:
                        obj.data = mesh
                        if obj == controller and not len(mesh.vertices):
                            registry.use_controller_mesh = False
                    else:
                        if obj == registry.grouped_object:
                            registry.grouped_object = None
                        if obj == controller:
                            registry.use_controller_mesh = False
                        for parent in list(obj.users_collection):
                            if parent in input_collections:
                                removed_links.append((parent, obj))
                                parent.objects.unlink(obj)
                bpy.context.view_layer.update()
                model.read_network(controller)
            except Exception:
                for obj, mesh in old_data.items():
                    obj.data = mesh
                registry.grouped_object, registry.use_controller_mesh = old_grouped, old_base
                registry.source_collection = old_collection
                for parent, obj in removed_links:
                    parent.objects.link(obj)
                if new_object is not None:
                    bpy.data.objects.remove(new_object, do_unlink=True)
                    new_object = None
                if created_collection is not None:
                    bpy.data.collections.remove(created_collection)
                raise
            # Only obsolete source objects are removed; the controller remains.
            # Blender's native undo restores these datablocks and their links.
            for obj, mesh in replacements.items():
                if mesh is None and obj != controller:
                    bpy.data.objects.remove(obj, do_unlink=True)
    except Exception:
        for mesh in prepared:
            if mesh.users == 0:
                bpy.data.meshes.remove(mesh)
        raise
    for mesh in old_data.values():
        if mesh.users == 0:
            bpy.data.meshes.remove(mesh)
    return new_object


class STREETS_OT_set_section_parameters(bpy.types.Operator):
    bl_idname = "streets.set_section_parameters"
    bl_label = "Set Section Parameters"
    bl_description = "Update width, offset and interpolation on every edge of the selected Section"
    bl_options = {'REGISTER', 'UNDO'}

    section_id: IntProperty(name="Section ID", default=-1, min=-1)
    width: FloatProperty(name="Width (m)", default=6.0, min=0.001, precision=3)
    offset: FloatProperty(name="Offset (m)", default=0.0, precision=3)
    interpolation: EnumProperty(name="Interpolation", items=[
        ('EXACT', "Exact polyline", "Follow straight source segments and retain their corners", 0),
        ('SMOOTH', "Smooth interpolation", "Interpolate through authored vertices with continuous tangents", 3)],
        default='SMOOTH')

    def draw(self, context):
        self.layout.prop(self,'width');self.layout.prop(self,'offset')
        controller=controller_for_object(context.active_object)
        if controller is not None and controller.get('blosm_original_span_network'):
            self.layout.label(text='Smooth interpolation')
        else:
            self.layout.prop(self,'interpolation')

    def invoke(self, context, event):
        try:
            controller, self.section_id = _selected_section(context, self.section_id)
            if controller.get('blosm_original_span_network'):
                from .original_span_editing import parameters
                self.width,self.offset=parameters(controller,self.section_id);self.interpolation='SMOOTH'
            else:
                network, _source = _section(controller, self.section_id)
                section = next(s for s in network.canonical.sections if s.id == self.section_id)
                self.width, self.offset = section.width, section.offset
                self.interpolation = ('EXACT' if network.section_records[self.section_id].interpolation == 0
                                      else 'SMOOTH')
        except (ValueError, RuntimeError) as exc:
            self.report({'ERROR'}, str(exc))
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self)

    def execute(self, context):
        try:
            controller, section_id = _selected_section(context, self.section_id)
            set_section_parameters(controller, section_id, width=self.width, offset=self.offset,
                                   interpolation=0 if self.interpolation == 'EXACT' else 3)
        except (ValueError, RuntimeError) as exc:
            self.report({'ERROR'}, str(exc))
            return {'CANCELLED'}
        return {'FINISHED'}


